#include "nfsug_owned_text.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"FAIL line %d\n",__LINE__);return 1;}}while(0)
int main(int argc,char**argv){CHECK(argc==3);FILE*f=fopen(argv[2],"rb");CHECK(f);fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);void*state=malloc(n);CHECK(state&&fread(state,1,n,f)==(size_t)n);fclose(f);NFAAndroidCore*c=nfa_core_open(argv[1]);CHECK(c&&nfa_core_load_state(c,state,n)&&nfa_core_capture_enable(c,1)&&nfa_core_capture_layers(c,1)&&nfa_core_capture_text_enable(c,1));unsigned frames=0,covered=0;uint64_t last[2]={0};unsigned char*data=malloc(76880);CHECK(data);for(unsigned i=0;i<90;i++){CHECK(nfa_core_step(c,i>=15&&i<17?128:0)==1);uint64_t info[5];if(!nfa_core_capture_layer_info(c,info))continue;size_t bytes=nfa_core_capture_menu_text(c,info[0],info[1],NULL,0);if(!bytes)continue;CHECK(bytes==76880);memset(data,165,bytes);CHECK(!nfa_core_capture_menu_text(c,info[0],info[1],data,bytes-1));for(unsigned k=0;k<bytes;k++)CHECK(data[k]==165);CHECK(nfa_core_capture_menu_text(c,info[0],info[1],data,bytes)==bytes);uint64_t header[10];memcpy(header,data,80);CHECK(header[0]==0x31544d4e&&header[3]==info[0]&&header[4]==info[1]&&header[9]==2);for(unsigned k=38480;k<bytes;k++){CHECK(data[k]<=1);covered+=data[k];}frames++;last[0]=info[0];last[1]=info[1];}CHECK(frames==89&&covered==19305);CHECK(nfa_core_load_state(c,state,n)&&!nfa_core_capture_menu_text(c,last[0],last[1],NULL,0));nfa_core_close(c);free(state);free(data);printf("PASS_ANDROID_NATIVE_MENU_TEXT snapshots=%u covered=%u short_atomic=true stale=true\n",frames,covered);return 0;}
